"""Real Django session revocation and current business-owner authorization."""
from django.conf import settings
from django.contrib.auth import (
    BACKEND_SESSION_KEY, HASH_SESSION_KEY, SESSION_KEY, get_user_model, logout,
)
from django.contrib.sessions.backends.db import SessionStore
from django.contrib.sessions.models import Session
from django.utils.crypto import constant_time_compare


def live_user(request):
    """Re-read the real session row, including for an already-open request."""
    key = request.COOKIES.get(settings.SESSION_COOKIE_NAME)
    if not key:
        return None
    values = SessionStore(session_key=key).load()
    if values.get(BACKEND_SESSION_KEY) not in settings.AUTHENTICATION_BACKENDS:
        return None
    identity = values.get(SESSION_KEY)
    if not identity:
        return None
    user = get_user_model().objects.filter(pk=identity, is_active=True).first()
    if user is None:
        return None
    if not constant_time_compare(values.get(HASH_SESSION_KEY, ''), user.get_session_auth_hash()):
        return None
    return user


def revoke(request):
    key = request.COOKIES.get(settings.SESSION_COOKIE_NAME)
    logout(request)
    return key is None or not Session.objects.filter(session_key=key).exists()


def job_for(request, identifier, Job):
    user = live_user(request)
    if user is None or not user.has_perm('console023.read_job'):
        return None
    job = Job.objects.filter(pk=identifier, owner_id=user.pk).first()
    if job is None:
        return None
    return {'job_id': str(job.pk), 'owner_id': job.owner_id,
            'status': job.status, 'result': job.result}

