/* The channel helps clear tabs; every protected read still checks the server. */
(() => {
  'use strict';
  const logoutKey = 'opsforge023.logout';
  const privatePrefix = 'opsforge023.private.';
  const channel = new BroadcastChannel('opsforge023.lifecycle');
  const pendingReads = new Set();
  const blobURLs = new Set();
  let generation = 0;

  function state(value) {
    document.getElementById('state').textContent = value;
  }

  function clearSensitive(value) {
    generation += 1;
    for (const controller of pendingReads) controller.abort();
    pendingReads.clear();
    for (const url of blobURLs) URL.revokeObjectURL(url);
    blobURLs.clear();
    document.getElementById('sensitive').textContent = '';
    const download = document.getElementById('download');
    download.removeAttribute('href');
    download.hidden = true;
    window.lastPrivate = null;
    for (const storage of [localStorage, sessionStorage]) {
      for (const key of Object.keys(storage)) {
        if (key.startsWith(privatePrefix)) storage.removeItem(key);
      }
    }
    state(value);
  }

  function csrf() {
    const item = document.cookie.split('; ').find(value => value.startsWith('csrftoken='));
    return item ? decodeURIComponent(item.slice('csrftoken='.length)) : '';
  }

  async function confirmRevocation() {
    clearSensitive('pending_server_revocation');
    try {
      const response = await fetch('/logout', {
        method: 'POST', credentials: 'same-origin', cache: 'no-store',
        headers: {'X-CSRFToken': csrf()},
      });
      const result = await response.json();
      if (!response.ok || result.revocation_confirmed !== true) throw new Error('unconfirmed');
      localStorage.setItem(logoutKey, 'confirmed');
      clearSensitive('signed_out');
      return true;
    } catch (error) {
      // The server may still hold the cookie's session. Do not claim success.
      localStorage.setItem(logoutKey, 'pending');
      clearSensitive('pending_server_revocation');
      return false;
    }
  }

  async function readPrivate(url) {
    if (localStorage.getItem(logoutKey)) {
      clearSensitive(localStorage.getItem(logoutKey) === 'pending' ? 'pending_server_revocation' : 'signed_out');
      return false;
    }
    const originalGeneration = generation;
    const controller = new AbortController();
    pendingReads.add(controller);
    try {
      const response = await fetch(url, {
        credentials: 'same-origin', cache: 'no-store', signal: controller.signal,
      });
      const payload = await response.json();
      if (!response.ok) {
        clearSensitive('signed_out');
        return false;
      }
      if (generation !== originalGeneration || localStorage.getItem(logoutKey)) return false;
      window.lastPrivate = payload;
      document.getElementById('sensitive').textContent = JSON.stringify(payload);
      if (document.body.dataset.view === 'download') {
        const url = URL.createObjectURL(new Blob([JSON.stringify(payload)], {type: 'application/json'}));
        blobURLs.add(url);
        const link = document.getElementById('download');
        link.href = url;
        link.hidden = false;
      }
      state('authenticated');
      return true;
    } catch (error) {
      // Cancellation and a network failure never authorize a new render.
      return false;
    } finally {
      pendingReads.delete(controller);
    }
  }

  function refresh() {
    return readPrivate(document.body.dataset.route);
  }

  function logoutNow() {
    localStorage.setItem(logoutKey, 'pending');
    clearSensitive('pending_server_revocation');
    channel.postMessage({type: 'logout'});
    return confirmRevocation();
  }

  function signalOnly() {
    if (localStorage.getItem(logoutKey)) {
      clearSensitive(localStorage.getItem(logoutKey) === 'pending' ? 'pending_server_revocation' : 'signed_out');
    }
  }

  async function resume() {
    clearSensitive('checking');
    const flag = localStorage.getItem(logoutKey);
    if (flag === 'pending') return confirmRevocation();
    if (flag === 'confirmed') return clearSensitive('signed_out');
    return refresh();
  }

  window.consoleSession = {logout: logoutNow, refresh, readPrivate};
  document.getElementById('logout').addEventListener('click', logoutNow);
  channel.addEventListener('message', signalOnly);
  addEventListener('storage', event => { if (event.key === logoutKey) signalOnly(); });
  addEventListener('pagehide', () => clearSensitive('hidden'));
  addEventListener('pageshow', resume);
  addEventListener('online', () => {
    if (localStorage.getItem(logoutKey) === 'pending') confirmRevocation();
  });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') clearSensitive('hidden');
    else resume();
  });
  resume();
})();

