class CDP:
    def __init__(self, url, evidence):
        self.socket = websocket.create_connection(url, timeout=4, suppress_origin=True,
                                                 http_no_proxy=['127.0.0.1', 'localhost'])
        self.evidence, self.counter, self.events = evidence, 0, []
        evidence.setdefault('CDP_connections', []).append({'url': url, 'original_messages': self.events})

    def receive(self):
        raw = self.socket.recv()
        self.events.append({'direction': 'received', 'raw': raw, 'monotonic_ns': time.monotonic_ns()})
        return json.loads(raw)

    def rpc(self, method, params=None):
        self.counter += 1
        value = {'id': self.counter, 'method': method, 'params': params or {}}
        raw = json.dumps(value, separators=(',', ':'))
        self.events.append({'direction': 'sent', 'raw': raw, 'monotonic_ns': time.monotonic_ns()})
        self.socket.send(raw)
        while True:
            response = self.receive()
            if response.get('id') == value['id']:
                assert 'error' not in response, {'method': method, 'reply': response}
                return response.get('result', {})

    def evaluate(self, expression, await_promise=True):
        result = self.rpc('Runtime.evaluate', {'expression': expression, 'awaitPromise': await_promise,
                                              'returnByValue': True})
        assert 'exceptionDetails' not in result, result
        return result.get('result', {}).get('value')

    def wait_event(self, method, predicate=lambda params: True, start=0):
        until = time.monotonic() + 5
        index = start
        while time.monotonic() < until:
            while index < len(self.events):
                row = self.events[index]
                index += 1
                if row['direction'] == 'received':
                    event = json.loads(row['raw'])
                    if event.get('method') == method and predicate(event.get('params', {})):
                        return event['params']
            self.receive()
        raise AssertionError('owned browser expected real protocol event missing: ' + method)

    def close(self):
        self.socket.close()


